  1	package com.sun.fortress.interpreter.evaluator.values;
  2	
  3	import com.sun.fortress.compiler.NamingCzar;
  4	import com.sun.fortress.exceptions.FortressException;
  5	import static com.sun.fortress.exceptions.ProgramError.error;
  6	import static com.sun.fortress.exceptions.ProgramError.errorMsg;
  7	import com.sun.fortress.interpreter.evaluator.Environment;
  8	import com.sun.fortress.interpreter.evaluator.EvalType;
  9	import com.sun.fortress.interpreter.evaluator.EvaluatorBase;
 10	import com.sun.fortress.interpreter.evaluator.types.FTraitOrObject;
 11	import com.sun.fortress.interpreter.evaluator.types.FType;
 12	import com.sun.fortress.nodes.IdOrOpOrAnonymousName;
 13	import com.sun.fortress.nodes.Type;
