 20	/**
 21	 * Coercion at run time.  A trait's or object's coerce declarations reach the
 22	 * interpreter as top-level functions, lifted by the disambiguator's
 23	 * CoercionLifter and named with NamingCzar.LIFTED_COERCION_PREFIX; a coercion
 24	 * is chosen here on the value the program has.
 25	 */
 26	public final class Coercions {
 27	
 28	    private Coercions() {
 29	    }
 30	
 31	    /**
 32	     * The lifted coercions to target, or null when target declares none.
 33	     */
 34	    private static Fcn liftedCoercions(FType target) {
 35	        if (!(target instanceof FTraitOrObject)) return null;
 36	        Environment e = target.getWithin();
 37	        if (e == null) return null;
 38	        FValue f = e.getTopLevel().getRootValueNull(NamingCzar.LIFTED_COERCION_PREFIX + target.getName());
 39	        return f instanceof Fcn ? (Fcn) f : null;
 40	    }
 41	
 42	    /**
 43	     * The coercion to target that applies to v without a coercion (coercions
 44	     * do not chain), or null.
 45	     */
 46	    static SingleFcn coercionFor(FType target, FValue v) {
 47	        Fcn lifted = liftedCoercions(target);
 48	        if (lifted == null) return null;
 49	        List<FValue> args = Collections.singletonList(v);
 50	        if (lifted instanceof OverloadedFunction) {
 51	            return ((OverloadedFunction) lifted).bestMatchWithoutCoercion(args);
 52	        }
 53	        SingleFcn f;
 54	        if (lifted instanceof GenericFunctionOrMethod) {
 55	            GenericFunctionOrMethod g = (GenericFunctionOrMethod) lifted;
 56	            try {
 57	                f = EvaluatorBase.inferAndInstantiateGenericFunction(args, g, g.getWithin());
 58	            }
 59	            catch (FortressException ex) {
 60	                return null;
 61	            }
 62	        } else if (lifted instanceof SingleFcn) {
 63	            f = (SingleFcn) lifted;
 64	        } else {
 65	            return null;
 66	        }
 67	        List<FValue> fargs = f.fixupArgCount(args);
 68	        return fargs != null && OverloadedFunction.argsMatchTypes(fargs, f.getDomain()) ? f : null;
 69	    }
 70	
 71	    /**
 72	     * v converted by the coercion c to target.
 73	     */
 74	    static FValue apply(SingleFcn c, FType target, FValue v) {
 75	        FValue r = c.applyInnerPossiblyGeneric(Collections.singletonList(v));
 76	        if (!target.typeMatch(r)) {
 77	            return error(errorMsg("Coercion ", c, " to ", target, " returned ", r, " of type ", r.type()));
 78	        }
 79	        return r;
 80	    }
 81	
 82	    /**
 83	     * v converted to target by one of target's coercions, or null when none
 84	     * applies to v.
 85	     */
 86	    public static FValue coerce(FType target, FValue v) {
 87	        SingleFcn c = coercionFor(target, v);
 88	        return c == null ? null : apply(c, target, v);
 89	    }
 90	
 91	    /**
 92	     * The value of a variable declared with type t in e, converted when it is
 93	     * not a t and a coercion to t applies.  Anything that goes wrong before a
 94	     * coercion is found leaves the value as it is, for the declaration's own
 95	     * check to report.
 96	     */
 97	    public static FValue coerceToDeclared(Type t, Environment e, FValue v) {
 98	        FType ft;
 99	        try {
100	            ft = new EvalType(e).evalType(t);
101	            if (ft.typeMatch(v)) return v;
102	        }
103	        catch (FortressException ex) {
104	            return v;
105	        }
106	        FValue c = coerce(ft, v);
107	        return c == null ? v : c;
108	    }
109	
110	    /**
111	     * The types a coercion to u is declared from.
112	     */
113	    private static List<FType> coercionSources(FType u) {
114	        Fcn lifted = liftedCoercions(u);
115	        List<FType> sources = new ArrayList<FType>();
116	        if (lifted instanceof OverloadedFunction) {
117	            for (Overload o : ((OverloadedFunction) lifted).getOverloads()) {
118	                addSource(o.getFn(), sources);
119	            }
120	        } else if (lifted instanceof SingleFcn) {
121	            addSource((SingleFcn) lifted, sources);
122	        }
123	        return sources;
124	    }
125	
126	    private static void addSource(SingleFcn f, List<FType> sources) {
127	        if (f instanceof GenericFunctionOrMethod) return;
128	        List<FType> d = f.getDomain();
129	        if (d.size() == 1) sources.add(d.get(0));
130	    }
131	
132	    /**
133	     * t is no less specific than u: t is a subtype of u, or t excludes, can be
134	     * coerced to, and rejects u.
135	     */
136	    private static boolean noLessSpecific(FType t, FType u) {
137	        if (t.subtypeOf(u)) return true;
138	        if (!t.excludesOther(u)) return false;
139	        boolean coercesTo = false;
140	        for (FType a : coercionSources(u)) {
141	            if (t.subtypeOf(a)) coercesTo = true;
142	        }
143	        if (!coercesTo) return false;
144	        for (FType a : coercionSources(t)) {
145	            if (!a.excludesOther(u)) return false;
146	        }
147	        return true;
148	    }
149	
150	    /**
151	     * The domain c is more specific than the domain d over the first n
152	     * parameter positions, element by element.
153	     */
154	    static boolean moreSpecific(List<FType> c, List<FType> d, int n) {
155	        boolean differ = false;
156	        for (int j = 0; j < n; j++) {
157	            FType t = Useful.clampedGet(c, j).deRest();
158	            FType u = Useful.clampedGet(d, j).deRest();
159	            if (!noLessSpecific(t, u)) return false;
160	            if (t != u) differ = true;
161	        }
162	        return differ;
163	    }
164	
165	    /**
166	     * An overloaded call with its coercions inserted: the chosen overload, and
167	     * for each argument position the coercion that converts it, or null.
168	     * Kept in the overloaded function's per-argument-type cache.
169	     */
170	    static final class CoercedCall extends SingleFcn {
171	        private final SingleFcn target;
172	        private final SingleFcn[] coercions;
173	
174	        CoercedCall(SingleFcn target, SingleFcn[] coercions) {
175	            super(target.getWithin());
176	            this.target = target;
177	            this.coercions = coercions;
178	        }
179	
180	        SingleFcn getTarget() {
181	            return target;
182	        }
183	
184	        int arity() {
185	            return coercions.length;
186	        }
187	
188	        List<FValue> convert(List<FValue> args) {
189	            List<FValue> oargs = target.fixupArgCount(args);
190	            List<FValue> res = new ArrayList<FValue>(oargs);
191	            List<FType> domain = target.getDomain();
192	            for (int j = 0; j < coercions.length; j++) {
193	                if (coercions[j] != null) {
194	                    res.set(j, apply(coercions[j], Useful.clampedGet(domain, j).deRest(), oargs.get(j)));
195	                }
196	            }
197	            return res;
198	        }
199	
200	        @Override
201	        public FValue applyInnerPossiblyGeneric(List<FValue> args) {
202	            List<FValue> cargs = convert(args);
203	            SingleFcn f = target;
204	            if (f instanceof FunctionalMethod) f = ((FunctionalMethod) f).getApplicableClosure(cargs);
205	            return f.applyInnerPossiblyGeneric(cargs);
206	        }
207	
208	        @Override
209	        public String at() {
210	            return target.at();
211	        }
212	
213	        public String stringName() {
214	            return target.stringName();
215	        }
216	
217	        @Override
218	        public List<FType> getDomain() {
219	            return target.getDomain();
220	        }
221	
222	        @Override
223	        public FType getRange() {
224	            return target.getRange();
225	        }
226	
227	        @Override
228	        public IdOrOpOrAnonymousName getFnName() {
229	            return target.getFnName();
230	        }
231	
232	        @Override
233	        public FType type() {
234	            return target.type();
235	        }
236	
237	        @Override
238	        public boolean seqv(FValue other) {
239	            return this == other;
240	        }
241	
242	        @Override
243	        public String toString() {
244	            return "coerced " + target;
245	        }
246	    }
247	}

