853	    private SingleFcn bestMatchInternal(List<FValue> args, List<Overload> someOverloads) {
854	        SingleFcn best_sfn = null;
855	
856	        if (debugMatch) {
857	            System.err.println("Seeking best match for " + args);
858	        }
859	
860	        for (Overload o : someOverloads) {
861	            if (o.getParams() == null) {
862	                bug(errorMsg("Unfinished overloaded function ", this));
863	            }
864	            SingleFcn sfn = o.getFn();
865	
866	            List<FValue> oargs = args;
867	
868	            if (sfn instanceof GenericFunctionOrMethod) {
869	                GenericFunctionOrMethod gsfn = (GenericFunctionOrMethod) sfn;
870	                try {
871	                    sfn = EvaluatorBase.inferAndInstantiateGenericFunction(oargs, gsfn, gsfn.getWithin());
872	                    if (debugMatch) System.err.println("Inferred from " + gsfn + " to " + sfn);
873	                }
874	                catch (FortressException pe) {
875	                    if (debugMatch) System.err.println("No match for " + gsfn);
876	                    continue; // No match, means no dice.
877	                }
878	
879	            } else if (debugMatch) {
880	                System.err.println("Trying w/o instantiation: " + sfn);
881	            }
882	
883	            oargs = sfn.fixupArgCount(args);
884	
885	            // Non-generic, old code.
